import{_ as e,c as o,o as d,b2 as a}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"工具类总览","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/utils/index.md","filePath":"docs/backend/utils/index.md"}'),n={name:"docs/backend/utils/index.md"};function i(s,t,l,c,r,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="工具类总览" tabindex="-1">工具类总览 <a class="header-anchor vp-link" href="#工具类总览" aria-label="Permalink to &quot;工具类总览&quot;">​</a></h1><p>QuickBoot <strong>未使用传统 JWT 工具类</strong>，会话由 <strong>Sa-Token</strong> 管理。下列为 <code>quickboot-common</code> 中实际存在的常用工具（按包）：</p><div class="vp-table"><table><thead><tr><th>类</th><th>包</th><th>用途</th></tr></thead><tbody><tr><td><code>ServletUtils</code></td><td><code>common.servlet</code></td><td>获取 Request/Response、参数、渲染 JSON</td></tr><tr><td><code>ValidatorUtils</code></td><td><code>common.validation</code></td><td>手动触发 Jakarta Validation</td></tr><tr><td><code>ExcelUtils</code></td><td><code>common.excel</code></td><td>EasyExcel 读写封装</td></tr><tr><td><code>I18nUtil</code></td><td><code>common.i18n</code></td><td>国际化消息</td></tr><tr><td><code>BeanUtil</code></td><td>Hutool</td><td>Bo/Entity/Vo 属性拷贝（项目约定）</td></tr></tbody></table></div><h2 id="缓存" tabindex="-1">缓存 <a class="header-anchor vp-link" href="#缓存" aria-label="Permalink to &quot;缓存&quot;">​</a></h2><p>Spring <code>CacheManager</code> 支持 <strong>Caffeine</strong>（默认）与 <strong>Redis</strong>。缓存名格式：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>cacheName#ttlSeconds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>示例：<code>clientSignNonce#300</code>。</p><h2 id="加密与密码" tabindex="-1">加密与密码 <a class="header-anchor vp-link" href="#加密与密码" aria-label="Permalink to &quot;加密与密码&quot;">​</a></h2><ul><li>用户密码：<strong>BCrypt</strong>（<code>PasswordCodec</code>）</li><li>配置/密钥字段：<strong>SM4</strong>（环境变量 <code>QC_SM4_KEY_HEX</code>）</li><li>Client 签名：<strong>HMAC-SHA256</strong>（<code>ClientSignService</code>）</li></ul><p>侧栏中的「JWT 工具」为历史规划项，请以 <strong>Sa-Token + OAuth2</strong> 为准。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../api/index.html" class="vp-link">接口规范</a></li><li><a href="./../modules/security-module.html" class="vp-link">安全防护模块</a></li></ul>',12)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
